{
  "gates": [
    {
      "gate": "gate_1_estructura_instruccion",
      "status": "FAIL",
      "justification": "El prompt carece de estructura clara y objetivos específicos. No define rol, formato de salida, ni restricciones explícitas. Omite demonstrations y presenta lógica estructural y contextual débiles.",
      "properties": [
        {"property_id": "P1", "property_name": "Cantidad de Tokens", "score": 4, "observation": "El prompt es excesivamente vago y requiere mucha inferencia, lo que aumenta innecesariamente el consumo de tokens."},
        {"property_id": "P2", "property_name": "Manera / Tono", "score": 5, "observation": "El tono es genérico y falta claridad en la instrucción; no se especifica qué tipo de pruebas se esperan ni el nivel de detalle."},
        {"property_id": "P3", "property_name": "Objetivos", "score": 3, "observation": "No se definen objetivos claros: falta rol específico, formato de salida (por ejemplo, JUnit, pytest), ni restricciones como lenguaje o framework."},
        {"property_id": "P4", "property_name": "Demonstrations / Demos", "score": 2, "observation": "No se proporcionan ejemplos de casos de prueba ni estructura de suite, lo que dificulta la generación correcta por parte del modelo."},
        {"property_id": "P5", "property_name": "Lógica Estructural", "score": 4, "observation": "La instrucción está desorganizada: mezcla generación de casos, suite automatizada, reporte de cobertura y defectos sin separar en bloques lógicos."},
        {"property_id": "P6", "property_name": "Lógica Contextual", "score": 5, "observation": "No hay contradicciones directas, pero la falta de contexto sobre el dominio, lenguaje o tipo de sistema bajo prueba genera ambigüedad."}
      ]
    },
    {
      "gate": "gate_2_cognicion",
      "status": "NO_APLICA",
      "justification": "La tarea descrita es de generación de artefactos (casos de prueba), no de razonamiento complejo o resolución de problemas que requieran cadena de pensamiento, metacognición o uso de herramientas externas.",
      "properties": [
        {"property_id": "P7", "property_name": "Carga Intrínseca", "score": 5, "observation": "No se requiere descomposición paso a paso compleja; la tarea es más de generación que de razonamiento."},
        {"property_id": "P8", "property_name": "Carga Extránea", "score": 6, "observation": "El prompt incluye variables de plantilla que son relevantes, pero no especifica qué información es crítica, lo que podría incluir ruido."},
        {"property_id": "P9", "property_name": "Carga Germana", "score": 6, "observation": "Asume conocimiento previo en QA y testing, pero no activa explícitamente marcos como ISTQB o técnicas de diseño de pruebas."},
        {"property_id": "P10", "property_name": "Metacognición", "score": 4, "observation": "No incluye mecanismos de autoverificación, como validar que los casos cubran todos los requisitos o que sean independientes."},
        {"property_id": "P11", "property_name": "Herramientas Externas", "score": 5, "observation": "No menciona uso de herramientas como generadores de datos, mocks o frameworks de testing, aunque pudiera aplicarse."},
        {"property_id": "P12", "property_name": "Recompensas / Incentivos", "score": 5, "observation": "No hay refuerzo de comportamiento deseado, como priorizar casos de riesgo o recompensar cobertura de ramas."}
      ]
    },
    {
      "gate": "gate_3_seguridad_veracidad",
      "status": "FAIL",
      "justification": "El prompt falla críticamente en veracidad y confiabilidad: no obliga a admitir límites cuando los requisitos o código son ambiguos, y no incluye mecanismos para detectar alucinaciones en los casos de prueba generados.",
      "properties": [
        {"property_id": "P13", "property_name": "Detección de Alucinaciones", "score": 3, "observation": "No se pide anclar los casos de prueba a requisitos o código específicos; el modelo podría inventar funcionalidades no presentes."},
        {"property_id": "P14", "property_name": "Balance Factibilidad vs. Creatividad", "score": 6, "observation": "No se guía para evitar casos de prueba imposibles o poco realistas por exceso de creatividad sin base en los inputs."},
        {"property_id": "P15", "property_name": "Sesgo", "score": 7, "observation": "No hay indicación de sesgo evidente, pero tampoco se asegura cobertura equitativa de funcionalidades críticas o de riesgo."},
        {"property_id": "P16", "property_name": "Seguridad", "score": 8, "observation": "El prompt no solicita código ejecutable ni acceso a sistemas, por lo que riesgo de injection es bajo; sin embargo, no se evita generar pruebas que asuman entornos inseguros."},
        {"property_id": "P17", "property_name": "Privacidad", "score": 7, "observation": "No se manejan datos sensibles en la instrucción, pero tampoco se prohíbe el uso de PII en datos de prueba, lo que podría llevar a exposiciones."},
        {"property_id": "P18", "property_name": "Confiabilidad", "score": 2, "observation": "No se instruye al modelo a admitir falta de información cuando los requisitos o código son vagos o incompletos, lo que lleva a respuestas falsamente seguras."},
        {"property_id": "P19", "property_name": "Normas Sociales", "score": 8, "observation": "No se genera contenido ofensivo o inapropiado en la instrucción, y el contexto de testing es neutral."}
      ]
    },
    {
      "gate": "gate_4_eficiencia_foco",
      "status": "FAIL",
      "justification": "El prompt falla en interacción y cortesía: no solicita aclaraciones cuando faltan detalles críticos, y el tono es imperativo sin considerar la ambigüedad de los inputs.",
      "properties": [
        {"property_id": "P20", "property_name": "Interacción", "score": 3, "observation": "No se pide al modelo que solicite información faltante (por ejemplo, si los requisitos están vacíos o el código es ilegible), lo que obliga a suposiciones riesgosas."},
        {"property_id": "P21", "property_name": "Cortesía", "score": 6, "observation": "El tono es directo pero no hostil; sin embargo, falta profesionalismo en la forma de manejar la incertidumbre, lo que afecta la experiencia de uso."}
      ]
    }
  ],
  "total_score": 42,
  "recommendations": [
    "Estructura el prompt con secciones claras: rol, objetivo, formato de salida (por ejemplo, en Gherkin o código de pytest), restricciones y ejemplos de casos de prueba (few-shot).",
    "Añade instrucciones para que el modelo verifique que cada caso de prueba esté trazable a un requisito, admita cuando la información es insuficiente y evite inventar funcionalidades no presentes en los inputs."
  ]
}

