      "properties": [
        {"property_id": "P20", "property_name": "Interacción", "score": 8, "observation": "No solicita aclaraciones proactivamente, pero sí obliga a señalar ambigüedades y proponer criterios asumidos, lo cual cubre parcialmente la necesidad de interacción cuando falta información."},
        {"property_id": "P21", "property_name": "Cortesía", "score": 9, "observation": "Tono profesional, respetuoso y adecuado para un contexto de colaboración técnica entre pares (ingeniero de QA y desarrollador)."}
      ]
    }
  ],
